-- tables/create_stops_view
CREATE OR REPLACE VIEW StopsView AS
SELECT
  row_id,
  stop_id,
  stop_name,
  stop_lat,
  stop_lon,
  location_type_name,
  parent_station,
  level_id,
  wheelchair_status,
  status
FROM (
  SELECT
    edt.row_id,
    edt.stop_id,
    edt.stop_name,
    edt.stop_lat,
    edt.stop_lon,
    edt.location_type_name,
    edt.parent_station,
    edt.level_id,
    edt.wheelchair_status,
    edt.status
  FROM EditStopTable edt
  WHERE edt.status IN ('new', 'edit', 'new edit')
  UNION ALL
  SELECT
    st.row_id,
    st.stop_id,
    st.stop_name,
    st.stop_lat,
    st.stop_lon,
    st.location_type_name,
    st.parent_station,
    st.level_id,
    st.wheelchair_status,
    '' AS status
  FROM stops st
  WHERE NOT EXISTS (
    SELECT 1
    FROM EditStopTable edt
    WHERE edt.row_id = st.row_id
      AND edt.status = 'deleted'
  )
  AND NOT EXISTS (
    SELECT 1
    FROM EditStopTable edt
    WHERE edt.row_id = st.row_id
      AND edt.status = 'edit'
  )
) combined;

-- tables/create_pathways_view
CREATE OR REPLACE VIEW PathwaysView AS
SELECT
  row_id,
  pathway_id,
  from_stop_id,
  to_stop_id,
  pathway_mode,
  is_bidirectional,
  length,
  traversal_time,
  stair_count,
  max_slope,
  min_width,
  signposted_as,
  reversed_signposted_as,
  pathway_mode_name,
  direction_type,
  status
FROM (
  -- Edited or new pathways from EditPathwayTable
  SELECT
    edt.row_id,
    edt.pathway_id,
    edt.from_stop_id,
    edt.to_stop_id,
    edt.pathway_mode,
    edt.is_bidirectional,
    edt.length,
    edt.traversal_time,
    edt.stair_count,
    edt.max_slope,
    edt.min_width,
    edt.signposted_as,
    edt.reversed_signposted_as,
    pathway_mode_to_name(edt.pathway_mode) AS pathway_mode_name,
    bidirectional_to_direction(edt.is_bidirectional) AS direction_type,
    edt.status
  FROM EditPathwayTable edt
  WHERE edt.status IN ('new', 'edit', 'new edit')

  UNION ALL

  -- Original pathways from pathways table
  SELECT
    pt.row_id,
    pt.pathway_id,
    pt.from_stop_id,
    pt.to_stop_id,
    pt.pathway_mode,
    pt.is_bidirectional,
    pt.length,
    pt.traversal_time,
    pt.stair_count,
    pt.max_slope,
    pt.min_width,
    pt.signposted_as,
    pt.reversed_signposted_as,
    pt.pathway_mode_name,
    pt.direction_type,
    '' AS status
  FROM pathways pt
  WHERE NOT EXISTS (
    SELECT 1
    FROM EditPathwayTable edt
    WHERE edt.row_id = pt.row_id
      AND edt.status = 'deleted'
  )
  AND NOT EXISTS (
    SELECT 1
    FROM EditPathwayTable edt
    WHERE edt.row_id = pt.row_id
      AND edt.status = 'edit'
  )
  AND NOT EXISTS (
    SELECT 1
    FROM EditPathwayTable edt
    WHERE edt.pathway_id = pt.pathway_id
      AND edt.status = 'new edit'
  )
) combined;

